def diff(a, b):
    out = []
    _walk("$", a, b, out)
    return sorted(out)

def _walk(path, a, b, out):
    if isinstance(a, dict) and isinstance(b, dict):
        for k in a:
            if k not in b:
                out.append(f"- {path}.{k}: {json.dumps(a[k], sort_keys=True)}")
            else:
                _walk(path + "." + k, a[k], b[k], out)
        for k in b:
            if k not in a:
                out.append(f"+ {path}.{k}: {json.dumps(b[k], sort_keys=True)}")
    elif isinstance(a, list) and isinstance(b, list):
        for i in range(min(len(a), len(b))):
            _walk(f"{path}[{i}]", a[i], b[i], out)
        for i in range(len(b), len(a)) ... wait:
        for i in range(len(a), len(b)):  # extra in b
            out.append(f"+ {path}[{i}]: {json.dumps(b[i], sort_keys=True)}")
        for i in range(len(b), len(a)):
            out.append(f"- {path}[{i}]: {json.dumps(a[i], sort_keys=True)}")
    elif not _equal(a, b):
        out.append(f"~ {path}: {json.dumps(a, sort_keys=True)} -> {json.dumps(b, sort_keys=True)}")

def _equal(a, b):
    if type(a) is not type(b):
        return False
    if isinstance(a, dict):
        return set(a) == set(b) and all(_equal(a[k], b[k]) for k in a)
    if isinstance(a, list):
        return len(a) == len(b) and all(_equal(x, y) for x, y in zip(a, b))
    return a == b
```

